aggregator.py.as-is:
"""Roll up a deduplicated conversion stream into reportable numbers.

Marketing and finance read these numbers to attribute spend and reconcile
revenue. Everything here is read-only: it projects over the events that the
ingestion pipeline already decided to keep. If dedup over- or under-counts,
these totals inherit the error, which is exactly why the counts matter.
"""

from __future__ import annotations

from event_models import ConversionEvent, KNOWN_EVENT_NAMES, total_value_cents


def counts_by_name(events: list[ConversionEvent]) -> dict[str, int]:
    """Number of kept conversions per event name."""
    counts: dict[str, int] = {}
    for event in events:
        counts[event.event_name] = counts.get(event.event_name, 0) + 1
    return counts


def value_by_name(events: list[ConversionEvent]) -> dict[str, int]:
    """Total value (in cents) of kept conversions per event name."""
    totals: dict[str, int] = {}
    for event in events:
        totals[event.event_name] = totals.get(event.event_name, 0) + event.value_cents
    return totals


def value_by_source(events: list[ConversionEvent]) -> dict[str, int]:
    """Total value (in cents) grouped by reporting source."""
    totals: dict[str, int] = {}
    for event in events:
        totals[event.source] = totals.get(event.source, 0) + event.value_cents
    return totals


def total_conversions(events: list[ConversionEvent]) -> int:
    return len(events)


def total_revenue_cents(events: list[ConversionEvent]) -> int:
    return total_value_cents(events)


def unknown_event_names(events: list[ConversionEvent]) -> list[str]:
    """Names that fell outside the known set, sorted for stable display."""
    names = {e.event_name for e in events if e.event_name not in KNOWN_EVENT_NAMES}
    return sorted(names)


def purchase_revenue_cents(events: list[ConversionEvent]) -> int:
    return sum(e.value_cents for e in events if e.event_name == "Purchase")


def aggregate_result(result: dict[str, object]) -> dict[str, object]:
    """Build a reporting projection from an ingestion result dictionary."""
    kept = list(result.get("kept", []))  # type: ignore[arg-type]
    return {
        "total_conversions": total_conversions(kept),
        "total_revenue_cents": total_revenue_cents(kept),
        "counts_by_name": counts_by_name(kept),
        "value_by_name": value_by_name(kept),
        "value_by_source": value_by_source(kept),
        "purchase_revenue_cents": purchase_revenue_cents(kept),
        "dropped_count": int(result.get("dropped_count", 0)),
    }


def merge_aggregates(rows: list[dict[str, object]]) -> dict[str, object]:
    """Combine several per-run projections into one rollup."""
    total_conv = 0
    total_rev = 0
    counts: dict[str, int] = {}
    values: dict[str, int] = {}
    for row in rows:
        total_conv += int(row.get("total_conversions", 0))
        total_rev += int(row.get("total_revenue_cents", 0))
        for name, count in dict(row.get("counts_by_name", {})).items():  # type: ignore[arg-type]
            counts[name] = counts.get(name, 0) + int(count)
        for name, value in dict(row.get("value_by_name", {})).items():  # type: ignore[arg-type]
            values[name] = values.get(name, 0) + int(value)
    return {
        "run_count": len(rows),
        "total_conversions": total_conv,
        "total_revenue_cents": total_rev,
        "counts_by_name": counts,
        "value_by_name": values,
    }

