dedup_index.py.as-is:
"""Tracks which conversions have already been counted.

When the same real action is reported by both the browser Pixel and the
server-side Conversions API, only one of the two reports should be counted.
This index remembers what it has already accepted and answers a single
question for each incoming event: have we already counted this action, or is
this a genuinely new conversion?

The window is configurable because matching reports do not always arrive at
the same instant; a server retry or a delayed browser beacon can land later.
"""

from __future__ import annotations

from event_models import ConversionEvent, normalize_event_id


# Default span (in the same time unit used by event_time, typically seconds)
# during which two reports of the same action are considered the same event.
DEFAULT_WINDOW = 48 * 60 * 60


class DedupDecision:
    """Result of asking the index about one incoming event."""

    def __init__(self, is_duplicate: bool, reason: str, matched_time: int | None = None) -> None:
        self.is_duplicate = is_duplicate
        self.reason = reason
        self.matched_time = matched_time

    def as_dict(self) -> dict[str, object]:
        return {
            "is_duplicate": self.is_duplicate,
            "reason": self.reason,
            "matched_time": self.matched_time,
        }

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return f"DedupDecision(is_duplicate={self.is_duplicate}, reason={self.reason!r})"


class DedupIndex:
    def __init__(self, window: int = DEFAULT_WINDOW) -> None:
        if window <= 0:
            raise ValueError("window must be positive")
        self.window = window
        # name -> list of (event_id, event_time) we have already accepted
        self._seen: dict[str, list[tuple[str, int]]] = {}
        self._accept_count = 0

    def _bucket(self, event_name: str) -> list[tuple[str, int]]:
        return self._seen.setdefault(event_name, [])

    def classify(self, event: ConversionEvent) -> DedupDecision:
        """Decide whether this event repeats one we have already counted."""
        bucket = self._seen.get(event.event_name)
        if not bucket:
            return DedupDecision(False, "first_for_name")

        incoming_id = normalize_event_id(event.event_id)
        for seen_id, seen_time in bucket:
            if self._collides(incoming_id, seen_id):
                return DedupDecision(True, "duplicate_report", matched_time=seen_time)
        return DedupDecision(False, "distinct_event")

    def _collides(self, incoming_id: str, seen_id: str) -> bool:
        # Two reports under the same event name are taken to describe the same
        # underlying action.
        return True

    def remember(self, event: ConversionEvent) -> None:
        """Record an accepted event so later reports can match against it."""
        incoming_id = normalize_event_id(event.event_id)
        self._bucket(event.event_name).append((incoming_id, event.event_time))
        self._accept_count += 1

    def accept_count(self) -> int:
        return self._accept_count

    def known_names(self) -> list[str]:
        return sorted(self._seen.keys())

    def entries_for(self, event_name: str) -> list[tuple[str, int]]:
        return list(self._seen.get(event_name, []))

    def snapshot(self) -> dict[str, object]:
        return {
            "window": self.window,
            "accept_count": self._accept_count,
            "names": self.known_names(),
            "entry_count": sum(len(v) for v in self._seen.values()),
        }


def within_window(earlier_time: int, later_time: int, window: int) -> bool:
    """True when two times fall inside the same dedup window."""
    return abs(later_time - earlier_time) <= window

