event_models.py.as-is:
"""Domain models for conversion events arriving from two sources.

A conversion (purchase, lead, add-to-cart, etc.) can be reported twice for the
same real action: once by the browser Pixel and once by the server-side
Conversions API. The ingestion layer needs typed records it can compare, plus
a few helpers for normalizing source labels and reading the matching key.
"""

from __future__ import annotations

from dataclasses import dataclass, field


PIXEL = "pixel"
CAPI = "capi"

VALID_SOURCES = {PIXEL, CAPI}

# Event names the pipeline knows how to count. Anything outside this set is
# still ingested but flagged so analysts can follow up.
KNOWN_EVENT_NAMES = {
    "Purchase",
    "Lead",
    "AddToCart",
    "CompleteRegistration",
    "InitiateCheckout",
    "Subscribe",
}


def normalize_source(raw: str) -> str:
    """Map a free-form source label onto the canonical pixel/capi values."""
    if raw is None:
        raise ValueError("source required")
    cleaned = raw.strip().lower()
    if cleaned in {"pixel", "browser", "web"}:
        return PIXEL
    if cleaned in {"capi", "server", "conversions_api", "conversions-api"}:
        return CAPI
    raise ValueError(f"unsupported source: {raw!r}")


def normalize_event_id(raw: str | None) -> str:
    """Trim an event id to its comparable form.

    An empty or whitespace-only id is treated as "no id" and returned as an
    empty string. Callers decide what that means for matching.
    """
    if raw is None:
        return ""
    return raw.strip()


@dataclass(frozen=True)
class ConversionEvent:
    event_name: str
    event_id: str
    source: str
    event_time: int
    value_cents: int = 0
    currency: str = "USD"
    metadata: tuple = field(default_factory=tuple)

    def __post_init__(self) -> None:
        if not self.event_name or not self.event_name.strip():
            raise ValueError("event_name required")
        if self.source not in VALID_SOURCES:
            raise ValueError(f"unsupported source: {self.source!r}")
        if self.event_time < 0:
            raise ValueError("event_time must be non-negative")
        if self.value_cents < 0:
            raise ValueError("value_cents must be non-negative")
        if not self.currency or not self.currency.strip():
            raise ValueError("currency required")

    @property
    def has_event_id(self) -> bool:
        return bool(self.event_id and self.event_id.strip())

    @property
    def is_server_side(self) -> bool:
        return self.source == CAPI

    @property
    def is_known_name(self) -> bool:
        return self.event_name in KNOWN_EVENT_NAMES

    def dedup_key(self) -> tuple[str, str]:
        """The identity used to recognize a re-report of the same action."""
        return (self.event_name, normalize_event_id(self.event_id))

    def describe(self) -> str:
        tag = self.event_id if self.has_event_id else "<no-id>"
        return f"{self.event_name}/{self.source}/{tag}@{self.event_time}"


def make_event(
    event_name: str,
    source: str,
    event_time: int,
    event_id: str | None = None,
    value_cents: int = 0,
    currency: str = "USD",
) -> ConversionEvent:
    """Convenience builder that normalizes source and id before constructing."""
    return ConversionEvent(
        event_name=event_name,
        event_id=normalize_event_id(event_id),
        source=normalize_source(source),
        event_time=event_time,
        value_cents=value_cents,
        currency=currency,
    )


def sort_events_for_ingestion(events: list[ConversionEvent]) -> list[ConversionEvent]:
    """Stable order for processing: earliest time first, then source, then id.

    Server events sort before browser events at the same time so the tie rule
    can prefer the server-side report when two reports collide.
    """
    source_rank = {CAPI: 0, PIXEL: 1}
    return sorted(
        events,
        key=lambda e: (e.event_time, source_rank.get(e.source, 9), e.event_name, e.event_id),
    )


def total_value_cents(events: list[ConversionEvent]) -> int:
    return sum(e.value_cents for e in events)

