ingestion_pipeline.py.as-is:
"""Consumes a mixed stream of Pixel and Conversions API events.

Both sources can report the same real conversion. The pipeline walks the
stream in time order, asks the dedup index whether each event repeats one it
already accepted, keeps the events that survive, and records what it dropped so
analysts can audit the run.

Flow: ingest_stream -> DedupIndex.classify/remember -> ConversionEvent helpers.
"""

from __future__ import annotations

from dedup_index import DedupIndex, DEFAULT_WINDOW
from event_models import (
    ConversionEvent,
    sort_events_for_ingestion,
)


class IngestionResult:
    def __init__(self) -> None:
        self.kept: list[ConversionEvent] = []
        self.dropped: list[ConversionEvent] = []
        self.audit: list[dict[str, object]] = []

    def record_kept(self, event: ConversionEvent, reason: str) -> None:
        self.kept.append(event)
        self.audit.append(
            {
                "action": "kept",
                "reason": reason,
                "event_name": event.event_name,
                "event_id": event.event_id,
                "source": event.source,
                "event_time": event.event_time,
            }
        )

    def record_dropped(self, event: ConversionEvent, reason: str, matched_time: int | None) -> None:
        self.dropped.append(event)
        self.audit.append(
            {
                "action": "dropped",
                "reason": reason,
                "event_name": event.event_name,
                "event_id": event.event_id,
                "source": event.source,
                "event_time": event.event_time,
                "matched_time": matched_time,
            }
        )

    def as_dict(self) -> dict[str, object]:
        return {
            "kept_count": len(self.kept),
            "dropped_count": len(self.dropped),
            "kept": self.kept,
            "dropped": self.dropped,
            "audit": self.audit,
        }


def ingest_stream(
    events: list[ConversionEvent],
    window: int = DEFAULT_WINDOW,
) -> dict[str, object]:
    """Deduplicate a mixed Pixel + CAPI stream and report what survived."""
    index = DedupIndex(window=window)
    result = IngestionResult()

    for event in sort_events_for_ingestion(events):
        decision = index.classify(event)
        if decision.is_duplicate:
            result.record_dropped(event, decision.reason, decision.matched_time)
            continue
        index.remember(event)
        result.record_kept(event, decision.reason)

    return result.as_dict()


def ingest_with_index(
    events: list[ConversionEvent],
    index: DedupIndex,
) -> dict[str, object]:
    """Run ingestion against a caller-owned index (used for streaming runs)."""
    result = IngestionResult()
    for event in sort_events_for_ingestion(events):
        decision = index.classify(event)
        if decision.is_duplicate:
            result.record_dropped(event, decision.reason, decision.matched_time)
            continue
        index.remember(event)
        result.record_kept(event, decision.reason)
    return result.as_dict()


class ConversionIngestor:
    """Stateful ingestor that keeps its dedup index across batches."""

    def __init__(self, window: int = DEFAULT_WINDOW) -> None:
        self.index = DedupIndex(window=window)
